import{_ as e}from"./chunks/overview-hero.D7m_mGxJ.js";import{_ as t,o as r,c as o,a3 as n}from"./chunks/framework.D1iekJsc.js";const m=JSON.parse('{"title":"Welcome","description":"MiniTavern Ultra handbook — mobile AI roleplay, character cards, BYOK, Ollama/LM Studio. SillyTavern-style chat on iOS/Android.","frontmatter":{"title":"Welcome","description":"MiniTavern Ultra handbook — mobile AI roleplay, character cards, BYOK, Ollama/LM Studio. SillyTavern-style chat on iOS/Android.","head":[["meta",{"name":"keywords","content":"tavern,AI tavern,MiniTavern,AI companion,AI friend,AI local chat,Silly Tavern,SillyTavern,Silly Tavern mobile,Silly Tavern Android,Silly Tavern iOS,AI roleplay,character card,AI chat,mobile AI,offline AI,AI story,local LLM,Ollama,LM Studio,lorebook,regex,BYOK,user guide,docs,AI chat client"}],["meta",{"property":"og:title","content":"Welcome · MiniTavern Docs"}],["meta",{"property":"og:description","content":"MiniTavern Ultra handbook — mobile AI roleplay, character cards, BYOK, Ollama/LM Studio. SillyTavern-style chat on iOS/Android."}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/en"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/en"}]]},"headers":[],"relativePath":"en/index.md","filePath":"en/index.md","lastUpdated":1787224147000}'),l={name:"en/index.md"};function i(d,a,s,c,u,h){return r(),o("div",null,[...a[0]||(a[0]=[n('<h1 id="welcome" tabindex="-1">Welcome <a class="header-anchor" href="#welcome" aria-label="Permalink to &quot;Welcome&quot;">​</a></h1><div class="overview-hero"><p><img src="'+e+'" alt="MiniTavern Ultra app screens"></p></div><h2 id="about-the-app" tabindex="-1">About the app <a class="header-anchor" href="#about-the-app" aria-label="Permalink to &quot;About the app&quot;">​</a></h2><p><strong>MiniTavern Ultra</strong> is an <strong>AI roleplay chat</strong> app.</p><p><strong>Create a companion. Play your story.</strong> — one character card, two ways to begin.</p><p>Import or create characters, then chat with your own cloud API or local model. Keys and chat data stay on your device first.</p><h2 id="what-you-can-do" tabindex="-1">What you can do <a class="header-anchor" href="#what-you-can-do" aria-label="Permalink to &quot;What you can do&quot;">​</a></h2><ol><li><strong>Create your own AI companion</strong> — personality, tone, and relationship are yours to shape.</li><li><strong>Bring idols and favorites closer</strong> — import community cards (SillyTavern-friendly formats).</li><li><strong>Play long stories</strong> — lorebook, regex, per-chat model and appearance.</li><li><strong>Use your own models</strong> — cloud APIs or Ollama / LM Studio on your PC.</li></ol><h2 id="quick-start" tabindex="-1">Quick start <a class="header-anchor" href="#quick-start" aria-label="Permalink to &quot;Quick start&quot;">​</a></h2><ol><li><strong>Configure a model</strong>: Settings → <a href="/ultra_guides/en/manual/model-link">Model link</a> → New, Test, set as default.</li><li><strong>Import or create a character</strong>: Characters → <a href="/ultra_guides/en/manual/chara-card">Import or create</a>.</li><li><strong>Start chatting</strong>: open a chat from the character — companion mode or in-character play, your choice.</li></ol><p>More detail: <a href="/ultra_guides/en/manual/getting-started">Getting started</a>. Local deploy: <a href="/ultra_guides/en/local/">overview</a> · <a href="/ultra_guides/en/quickstart">language-model quickstart</a> · <a href="/ultra_guides/en/local/image-gen/">image gen</a>. Free quotas: <a href="/ultra_guides/en/free-cloud/">Free cloud APIs</a>.</p><h2 id="handbook-entry-points" tabindex="-1">Handbook entry points <a class="header-anchor" href="#handbook-entry-points" aria-label="Permalink to &quot;Handbook entry points&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Section</th><th>Description</th></tr></thead><tbody><tr><td><a href="/ultra_guides/en/manual/">Manual home</a></td><td>Suggested reading order and overview</td></tr><tr><td><a href="/ultra_guides/en/manual/model-link">Models</a></td><td>Links, parameters, Test, and troubleshooting</td></tr><tr><td><a href="/ultra_guides/en/free-cloud/">Free cloud APIs</a></td><td>Vendor free tiers and how to fill Keys</td></tr><tr><td><a href="/ultra_guides/en/local/">Run local models</a></td><td>Local language / image deploy</td></tr><tr><td><a href="/ultra_guides/en/manual/chara-card">Characters</a></td><td>Import, edit, start chats</td></tr><tr><td><a href="/ultra_guides/en/manual/chat">Chat</a></td><td>Conversation and session settings</td></tr><tr><td><a href="/ultra_guides/en/manual/lorebook">Advanced</a></td><td>Lorebook, regex, persona, backup</td></tr></tbody></table><p>In the app: Settings → <strong>Help &amp; feedback</strong> → <strong>User Manual</strong>.</p><h2 id="faq-short" tabindex="-1">FAQ (short) <a class="header-anchor" href="#faq-short" aria-label="Permalink to &quot;FAQ (short)&quot;">​</a></h2><p><strong>Q: What is MiniTavern Ultra?</strong><br> A: An AI roleplay chat app. Create your own companion or import cards and play in character; use your own API Key or a local model.</p><p><strong>Q: Is my data uploaded to your servers?</strong><br> A: Chats, characters, and keys stay on-device by default; model calls go to the third-party or local address <strong>you</strong> configure. See <a href="/ultra_guides/en/privacy">Privacy</a>.</p><p><strong>Q: Can I play without an API?</strong><br> A: You need a cloud Key, or follow <a href="/ultra_guides/en/local/">Run local models</a> to host on a PC then connect the phone. Common free quotas: <a href="/ultra_guides/en/free-cloud/">Free cloud APIs</a>; local image gen: <a href="/ultra_guides/en/local/image-gen/">Image model deploy</a>.</p><h2 id="download-and-policies" tabindex="-1">Download and policies <a class="header-anchor" href="#download-and-policies" aria-label="Permalink to &quot;Download and policies&quot;">​</a></h2><ul><li>Top bar <strong>Download MiniTavern</strong> · <a href="https://minitavern.github.io/ultra_website/" target="_blank" rel="noreferrer">Product site</a></li><li><a href="/ultra_guides/en/privacy">Privacy</a> · <a href="/ultra_guides/en/terms">Terms</a></li></ul>',20)])])}const y=t(l,[["render",i]]);export{m as __pageData,y as default};
